public str process(str _imageId)
{
    str				ret;
    SysDictClass	DC;

    if (SysTest::hasMethod(this,_imageId))
    {
        DC = new SysDictClass(classIdGet(this));

        return DC.callObject(_imageId,this);
    }

    return ret;
}

public str attachListToCart()
{
    str						base64;

    base64 = TFMImageCombiner::combineImage(base64,resourceStr(MobCartForWarehouseEmpty),50,50,100,100,false);
    base64 = TFMImageCombiner::combineImage(base64,resourceStr(TFMPickIcon),65,76,200,200,false);
    base64 = TFMImageCombiner::combineImage(base64,resourceStr(TFMStatePlus),85,80,30,30,true);

    return base64;
}

